@aware([
    'placeholder' => null,
    'invalid' => false,
    'disabled' => false,
    'clearable' => false,
    'size' => null,
])

@php
    use App\Support\Stencil\Form\FormControlClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $triggerAttributes = $interactionState->apply(
        $attributes
            ->class([
                'time-picker__trigger',
                'group flex w-full min-w-0 items-center justify-between gap-2 text-left',
                $formControl->fieldSurfaceClasses($size, includeReadOnly: false, cursor: 'pointer'),
                $invalid ? 'border-red-500' : null,
            ])
            ->merge([
                'type' => 'button',
                'aria-haspopup' => 'listbox',
                'aria-expanded' => 'false',
            ]),
        ['nativeDisabled' => true],
    );
@endphp

<button {{ $triggerAttributes }} data-time-picker-trigger>
    <span class="flex min-w-0 flex-1 items-center gap-2">
        <x-ui::icon name="clock" class="size-4 shrink-0 opacity-50" />
        <x-ui::time-picker.selected :$placeholder />
    </span>
    @if ($clearable)
        <span
            class="inline-flex size-6 cursor-pointer items-center justify-center rounded-md text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800"
            data-time-picker-clear
            role="button"
            tabindex="-1"
            aria-label="{{ __('stencil-ui::messages.time_picker_clear') }}"
        >
            <x-ui::icon name="x" class="size-3.5" />
        </span>
    @endif
    <x-ui::icon name="chevron-down" class="size-4 shrink-0 opacity-50" />
</button>

@props([
    'name' => null,
    'value' => null,
    'placeholder' => null,
    'type' => 'button',
    'invalid' => false,
    'disabled' => false,
    'clearable' => false,
    'size' => null,
    'withSeconds' => false,
    'step' => 30,
    'unavailable' => null,
    'timezone' => null,
    'locale' => null,
    'shortcut' => true,
])

@aware([
    'fieldInvalid' => false,
])

@php
    use App\Support\Stencil\Chrono\ChronoFormatter;

    $invalid = $invalid || $fieldInvalid;
    $resolvedTimezone = ChronoFormatter::resolveTimezone($timezone);
    $resolvedLocale = $locale ?? app()->getLocale();
    $resolvedValue = ChronoFormatter::normalizeTimeValue($value, $withSeconds);
    $resolvedPlaceholder = $placeholder ?? __('stencil-ui::messages.time_picker_placeholder');

    if (is_array($unavailable)) {
        $unavailable = collect($unavailable)->implode(',');
    }
@endphp

<div
    {{ $attributes->except(['shortcut'])->class(['time-picker relative min-w-0', 'w-full' => ! filled($attributes->get('class'))]) }}
    data-time-picker
    data-time-picker-step="{{ $step }}"
    @if ($withSeconds) data-time-picker-seconds @endif
    data-time-picker-locale="{{ $resolvedLocale }}"
    data-time-picker-timezone="{{ $resolvedTimezone }}"
    @if (filled($unavailable)) data-time-picker-unavailable="{{ $unavailable }}" @endif
>
    @if (filled($name))
        <input type="hidden" name="{{ $name }}" value="{{ $resolvedValue }}" data-time-picker-hidden-input />
    @else
        <input type="hidden" value="{{ $resolvedValue }}" data-time-picker-hidden-input />
    @endif

    @if ($shortcut)
        @if ($type === 'input')
            <x-ui::time-picker.input :$placeholder :$invalid :$disabled :$clearable :$size />
        @else
            <x-ui::time-picker.button :$placeholder :$invalid :$disabled :$clearable :$size />
        @endif
    @else
        {{ $slot }}
    @endif

    <div
        class="time-picker__panel fixed z-50 hidden max-h-80 min-w-48 overflow-y-auto rounded-lg border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-800 dark:bg-zinc-950"
        data-time-picker-panel
        hidden
    ></div>
</div>

@props([
    'placeholder' => null,
])

<span
    {{
        $attributes->class([
            'time-picker__value block min-w-0 flex-1 truncate text-left',
            'data-placeholder:text-zinc-500 dark:data-placeholder:text-zinc-400',
        ])->merge([
            'data-placeholder' => filled($placeholder) ? 'true' : null,
            'data-placeholder-text' => filled($placeholder) ? $placeholder : null,
        ])
    }}
    data-time-picker-value
>{{ $placeholder }}</span>

/**
 * Stencil — time picker (vanilla JS).
 */

import { ensurePanelPortaled, positionAnchoredPanel } from './chrono/popover.js';
import { formatTimeLabel } from './chrono/timezone.js';

const SELECTOR = '[data-time-picker]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initTimePickers(root = document) {
    root.querySelectorAll(SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement) || initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindTimePicker(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindTimePicker(root) {
    const hidden = root.querySelector('[data-time-picker-hidden-input]');
    const trigger = root.querySelector('[data-time-picker-trigger]');
    const panel = root.querySelector('[data-time-picker-panel]');
    const valueEl = root.querySelector('[data-time-picker-value]');
    const inputEl = root.querySelector('[data-time-picker-input]');

    if (!(hidden instanceof HTMLInputElement) || !(panel instanceof HTMLElement)) {
        return;
    }

    const step = parseInt(root.dataset.timePickerStep ?? '30', 10) || 30;
    const withSeconds = root.hasAttribute('data-time-picker-seconds');
    const locale = root.dataset.timePickerLocale ?? 'en';
    const timeZone = root.dataset.timePickerTimezone ?? 'UTC';
    const unavailable = (root.dataset.timePickerUnavailable ?? '')
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean);

    const portalMarker = document.createComment('stencil-time-picker-portal');
    let open = false;

    const options = buildOptions(step, withSeconds, unavailable);

    panel.innerHTML = '';
    options.forEach((time) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className =
            'flex w-full rounded-lg px-2 py-1.5 text-left text-sm tabular-nums hover:bg-zinc-100 dark:hover:bg-zinc-800';
        button.dataset.timePickerOption = time;
        button.textContent = formatTimeLabel(time, locale, timeZone, withSeconds);
        button.setAttribute('role', 'option');
        panel.appendChild(button);
    });

    function setOpen(next) {
        open = next;
        panel.hidden = !next;

        if (trigger instanceof HTMLElement) {
            trigger.setAttribute('aria-expanded', next ? 'true' : 'false');
        }

        if (next && trigger instanceof HTMLElement) {
            ensurePanelPortaled(panel, root, portalMarker);
            positionAnchoredPanel(panel, trigger);
            panel.focus();
        }
    }

    function apply(time) {
        hidden.value = time;

        if (!time) {
            if (valueEl instanceof HTMLElement) {
                valueEl.textContent = valueEl.getAttribute('data-placeholder-text') ?? '';
                valueEl.setAttribute('data-placeholder', 'true');
            }

            if (inputEl instanceof HTMLInputElement) {
                inputEl.value = '';
            }
        } else {
            const label = formatTimeLabel(time, locale, timeZone, withSeconds);

            if (valueEl instanceof HTMLElement) {
                valueEl.textContent = label;
                valueEl.removeAttribute('data-placeholder');
            }

            if (inputEl instanceof HTMLInputElement) {
                inputEl.value = label;
            }
        }

        panel.querySelectorAll('[data-time-picker-option]').forEach((el) => {
            if (el instanceof HTMLElement) {
                const selected = el.dataset.timePickerOption === time;
                el.setAttribute('aria-selected', selected ? 'true' : 'false');
                el.classList.toggle('bg-zinc-900', selected);
                el.classList.toggle('text-white', selected);
                el.classList.toggle('dark:bg-zinc-100', selected);
                el.classList.toggle('dark:text-zinc-900', selected);
                el.classList.toggle('hover:bg-zinc-100', !selected);
                el.classList.toggle('dark:hover:bg-zinc-800', !selected);
            }
        });

        hidden.dispatchEvent(new Event('input', { bubbles: true }));
        hidden.dispatchEvent(new Event('change', { bubbles: true }));
        setOpen(false);
    }

    trigger?.addEventListener('click', (event) => {
        event.preventDefault();
        setOpen(!open);
    });

    root.querySelectorAll('[data-time-picker-clear]').forEach((clear) => {
        clear.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            apply('');
        });
    });

    panel.addEventListener('click', (event) => {
        const option =
            event.target instanceof Element
                ? event.target.closest('[data-time-picker-option]')
                : null;

        if (option instanceof HTMLElement && option.dataset.timePickerOption) {
            apply(option.dataset.timePickerOption);
        }
    });

    document.addEventListener('pointerdown', (event) => {
        if (!open) {
            return;
        }

        const target = event.target;

        if (target instanceof Node && !root.contains(target) && !panel.contains(target)) {
            setOpen(false);
        }
    });

    if (hidden.value) {
        apply(hidden.value);
    }
}

/**
 * @param {number} step minutes
 * @param {boolean} withSeconds
 * @param {string[]} unavailable
 */
function buildOptions(step, withSeconds, unavailable) {
    const options = [];

    for (let minutes = 0; minutes < 24 * 60; minutes += step) {
        const h = Math.floor(minutes / 60);
        const m = minutes % 60;
        const value = withSeconds
            ? `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:00`
            : `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;

        if (!unavailable.includes(value)) {
            options.push(value);
        }
    }

    return options;
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initTimePickers(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initTimePickers());
    } else {
        initTimePickers();
    }
}

/**
 * Anchored floating panel (portal to body). Shared by select-like overlays and pickers.
 */

/**
 * @param {HTMLElement} panel
 * @param {HTMLElement} trigger
 * @param {{ gap?: number, viewportPadding?: number }} [options]
 */
export function positionAnchoredPanel(panel, trigger, options = {}) {
    const gap = options.gap ?? 6;
    const viewportPadding = options.viewportPadding ?? 8;

    const rect = trigger.getBoundingClientRect();

    panel.style.position = 'fixed';
    panel.style.left = `${Math.max(viewportPadding, rect.left)}px`;
    panel.style.zIndex = '200';

    if (options.fitContent) {
        panel.style.width = 'max-content';
        panel.style.minWidth = '';
    } else {
        panel.style.width = `${Math.max(rect.width, panel.offsetWidth || rect.width)}px`;
        panel.style.minWidth = `${rect.width}px`;
    }

    const wasHidden = panel.hidden;
    panel.hidden = false;
    panel.style.visibility = 'hidden';
    panel.style.pointerEvents = 'none';
    const panelHeight = panel.offsetHeight;
    panel.style.visibility = '';
    panel.style.pointerEvents = '';
    panel.hidden = wasHidden;

    let top = rect.bottom + gap;
    const maxBottom = window.innerHeight - viewportPadding;

    if (top + panelHeight > maxBottom) {
        const topAbove = rect.top - gap - panelHeight;

        if (topAbove >= viewportPadding) {
            top = topAbove;
        } else {
            panel.style.maxHeight = `${maxBottom - top}px`;
        }
    } else {
        panel.style.maxHeight = '';
    }

    panel.style.top = `${top}px`;
}

/**
 * @param {HTMLElement} panel
 * @param {HTMLElement} markerParent
 * @param {Comment} portalMarker
 */
export function ensurePanelPortaled(panel, markerParent, portalMarker) {
    if (panel.parentElement === document.body) {
        return;
    }

    if (markerParent && !portalMarker.parentNode) {
        markerParent.insertBefore(portalMarker, panel);
    }

    document.body.appendChild(panel);
    panel.dataset.stencilPortaled = 'true';
}

/**
 * @param {HTMLElement} panel
 * @param {HTMLElement} markerParent
 * @param {Comment} portalMarker
 */
export function restorePanelFromPortal(panel, markerParent, portalMarker) {
    if (panel.parentElement !== document.body) {
        return;
    }

    if (markerParent.isConnected) {
        if (portalMarker.parentNode === markerParent) {
            markerParent.insertBefore(panel, portalMarker.nextSibling);
        } else {
            markerParent.appendChild(panel);
        }
    }

    delete panel.dataset.stencilPortaled;
}

/**
 * @param {HTMLElement} root
 * @param {HTMLElement} panel
 * @param {() => void} onClose
 */
export function bindPopoverDismiss(root, panel, onClose) {
    const contains = (target) =>
        target instanceof Node && (root.contains(target) || panel.contains(target));

    document.addEventListener('pointerdown', (event) => {
        if (!contains(event.target)) {
            onClose();
        }
    });

    window.addEventListener(
        'scroll',
        () => {
            onClose();
        },
        true,
    );
}

import { DateValue } from './date-value.js';

/**
 * @param {string} timeZone IANA timezone
 */
export function todayInTimeZone(timeZone) {
    const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
    });

    const parts = formatter.formatToParts(new Date());
    const year = Number(parts.find((p) => p.type === 'year')?.value);
    const month = Number(parts.find((p) => p.type === 'month')?.value);
    const day = Number(parts.find((p) => p.type === 'day')?.value);

    return new DateValue(year, month, day);
}

/**
 * @param {DateValue} dateValue
 * @param {string} locale
 * @param {Intl.DateTimeFormatOptions} options
 */
export function formatDateValue(dateValue, locale, options = {}) {
    return new Intl.DateTimeFormat(locale, {
        ...options,
        timeZone: 'UTC',
    }).format(dateValue.getDate());
}

/**
 * Format a calendar date (YYYY-MM-DD) for the trigger label.
 *
 * @param {string} isoDate
 * @param {string} locale
 */
export function formatDateLabel(isoDate, locale) {
    if (!isoDate) {
        return '';
    }

    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(isoDate);

    if (!match) {
        return isoDate;
    }

    const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])));

    return new Intl.DateTimeFormat(locale, {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        timeZone: 'UTC',
    }).format(date);
}

/**
 * Format an ISO datetime for the trigger label.
 *
 * @param {string} isoDatetime
 * @param {string} locale
 * @param {string} timeZone
 * @param {boolean} withSeconds
 */
export function formatDateTimeLabel(isoDatetime, locale, timeZone, withSeconds = false) {
    if (!isoDatetime) {
        return '';
    }

    const date = new Date(isoDatetime);

    if (Number.isNaN(date.getTime())) {
        return isoDatetime;
    }

    return new Intl.DateTimeFormat(locale, {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        second: withSeconds ? '2-digit' : undefined,
        timeZone,
    }).format(date);
}

/**
 * Format a wall-clock time (HH:mm or HH:mm:ss) for labels.
 * Time-only values are timezone-independent — keep them on a UTC anchor so the
 * hour/minute never shift with the browser offset.
 *
 * @param {string} time HH:mm or HH:mm:ss
 * @param {string} locale
 * @param {string} [_timeZone] retained for call-site compatibility
 * @param {boolean} withSeconds
 */
export function formatTimeLabel(time, locale, _timeZone, withSeconds = false) {
    if (!time) {
        return '';
    }

    const [h, m, s] = time.split(':').map((v) => parseInt(v, 10) || 0);
    const date = new Date(Date.UTC(1970, 0, 1, h, m, s || 0));

    return new Intl.DateTimeFormat(locale, {
        hour: 'numeric',
        minute: '2-digit',
        second: withSeconds ? '2-digit' : undefined,
        timeZone: 'UTC',
    }).format(date);
}
